SELECT $j$trong-cay-chau-long-chau$j$, 'article', 'cham-soc', $j$🌿 Trồng cây kiểu chậu lồng chậu: đổi cây trong vài giây, rễ mát, không đổ$j$,
  $j$Chậu lồng chậu là chôn sẵn một chậu rỗng dưới đất rồi thả nguyên chậu cây vào. Cây đứng vững, rễ mát như trồng đất mà vẫn nhấc ra đổi cây khác trong vài giây. Bí quyết là lót sỏi đáy hố để nước thoát, nhất là mùa mưa miền Tây.$j$,
  $j$[{"type": "p", "text": "Trồng cây trong chậu thì dễ dời, nhưng chậu đặt trên nền sân nắng nóng nhanh khô, gió lật. Trồng thẳng xuống đất thì cây vững, nhưng muốn đổi cây khác lại phải đào bới. **Chậu lồng chậu** (chôn sẵn một chậu rỗng dưới đất rồi thả nguyên chậu cây vào) lấy được cái lợi của cả hai."}, {"type": "image", "file": "https://www.caycanhmientay.com/api/product-images/hoa-hong-0ecef56608773e1fb432f47e1cfff414.jpg?w=960", "caption": "Hoa hồng chậu tại vườn Cây Cảnh Miền Tây — loại cây hợp với cách chậu lồng chậu"}, {"type": "h2", "text": "📖 Chậu lồng chậu là gì?"}, {"type": "p", "text": "Bạn chôn một **chậu ngoài** (chậu nhựa rẻ tiền, rỗng) xuống luống hoặc bồn đất, miệng chậu ngang mặt đất. Cây vẫn sống trong **chậu trong** của nó; khi cần chỉ việc thả chậu trong vào, hoặc nhấc ra. Nhìn từ ngoài, cây như được trồng thẳng xuống đất."}, {"type": "h2", "text": "💡 Vì sao nên trồng kiểu này?"}, {"type": "list", "ordered": false, "items": ["**Đổi cây trong vài giây**: hoa tàn thì nhấc ra, thả chậu hoa mới vào — rất hợp để thay cây theo mùa hay chưng Tết.", "**Rễ mát hơn**: đất xung quanh che nắng cho thành chậu, rễ không bị nóng như chậu đặt trên nền xi măng.", "**Cây không đổ** khi gió mạnh, chó mèo không lật chậu.", "**Giữ cây lan mạnh trong khuôn**: bạc hà, rau má, cỏ lan không bò khắp luống.", "**Cây yếu mang đi chăm riêng** được ngay, không phải đào làm đứt rễ."]}, {"type": "h2", "text": "🪴 Cần chuẩn bị gì?"}, {"type": "list", "ordered": false, "items": ["Chậu ngoài: chậu nhựa đen có lỗ đáy, **lớn hơn chậu trong 1 cỡ** (ví dụ cây chậu C7 thì chôn chậu C8). Xem số đo các cỡ trong bài [chọn chậu và cỡ cây theo mã chậu C](/goc-cham-cay/chon-chau-va-co-cay-ma-chau-c).", "Chậu trong: chậu đang trồng cây, phải có lỗ thoát nước.", "Sỏi, đá dăm hoặc gạch vỡ để lót đáy hố.", "Xẻng nhỏ, bao tay."]}, {"type": "h2", "text": "🛠️ Làm từng bước như thế nào?"}, {"type": "list", "ordered": true, "items": ["Đào hố sâu hơn chiều cao chậu ngoài khoảng **10–15cm**.", "Đổ lớp sỏi 10–15cm dưới đáy hố — đây là bước quan trọng nhất để nước thoát.", "Đặt chậu ngoài vào hố, miệng chậu **cao hơn mặt đất 1–2cm** để nước mưa chảy tràn trên mặt đất không đổ vào khe chậu.", "Lấp đất quanh chậu ngoài, nén chặt.", "Thả chậu cây vào. Khe giữa hai chậu có thể phủ một lớp mùn, vỏ trấu hoặc sỏi trang trí cho kín."]}, {"type": "note", "title": "⚠️ Lưu ý mùa mưa miền Tây", "text": "Đất ruộng, đất thịt nặng hay chỗ trũng đọng nước thì đáy chậu ngoài dễ thành vũng nước — rễ cây trong ngâm nước sẽ thối. Mùa mưa nên nhấc thử chậu trong sau trận mưa lớn: thấy nước đọng dưới đáy thì lót thêm sỏi hoặc chuyển chỗ cao hơn. Đất ngập nước nhiều ngày thì không nên dùng cách này. Xem thêm [chăm cây mùa mưa miền Tây](/goc-cham-cay/cham-cay-mua-mua-mien-tay) và cách nhận biết [thối rễ](/benh-cay/thoi-re)."}, {"type": "h2", "text": "💧 Tưới cây chậu lồng chậu có khác gì không?"}, {"type": "p", "text": "Ít tưới hơn chậu đặt trên nền vì đất xung quanh giữ mát, nhưng **vẫn khô nhanh hơn cây trồng thẳng xuống đất** vì rễ chỉ nằm trong chậu. Kiểm tra bằng ngón tay: đất mặt khô 2–3cm thì tưới. Chậu càng nhỏ càng phải để ý mùa khô."}, {"type": "h2", "text": "🌿 Cây nào hợp với cách này?"}, {"type": "list", "ordered": false, "items": ["Cây hoa thay theo mùa: [hoa hồng](/san-pham/hoa-hong), [mai địa thảo](/san-pham/mai-dia-thao), cúc, vạn thọ chưng Tết.", "Cây thân củ có mùa ngủ như [tulip Thái](/san-pham/tulip-thai): hết mùa nhấc chậu ra cất, chỗ trống thay cây khác.", "Rau thơm hay bò lan: bạc hà, rau má, húng.", "Cây cần mang vào nhà khi trời xấu."]}, {"type": "h2", "text": "❓ Khi nào không nên dùng?"}, {"type": "list", "ordered": false, "items": ["Cây lớn, cây lâu năm muốn để cố định: trồng thẳng xuống đất cho rễ phát triển.", "Rễ đã mọc xuyên qua lỗ đáy xuống chậu ngoài: mỗi 1–2 tháng nhấc chậu lên xoay nhẹ để rễ không bám chặt; nếu rễ đã ra nhiều là lúc [thay chậu](/goc-cham-cay/thay-chau-cay-canh-dung-cach).", "Đất trũng, thường xuyên ngập."]}, {"type": "h2", "text": "📋 Tóm tắt"}, {"type": "table", "rows": [["Việc", "Cách làm"], ["Chậu ngoài", "Lớn hơn chậu cây 1 cỡ, có lỗ đáy"], ["Đáy hố", "Lót sỏi 10–15cm"], ["Miệng chậu", "Cao hơn mặt đất 1–2cm"], ["Tưới", "Khi đất mặt khô 2–3cm"], ["Kiểm tra", "Sau mưa lớn nhấc chậu xem có đọng nước"]]}, {"type": "products", "title": "Cây hoa đổi mùa cho sân vườn", "slugs": ["hoa-hong", "mai-dia-thao", "tulip-thai"]}, {"type": "p", "text": "Đang làm sân vườn nhỏ? Xem thêm [sân vườn nhỏ nhà phố](/goc-cham-cay/san-vuon-nho-nha-pho) và [chuẩn bị cây cảnh đón Tết](/goc-cham-cay/chuan-bi-cay-canh-don-tet)."}]$j$::jsonb, $j$https://www.caycanhmientay.com/api/product-images/hoa-hong-26961512bb04a663398a9893bb8019fd.jpg?w=960$j$, 5, 'Cây Cảnh Miền Tây',
  '["thoi-re"]'::jsonb, '["chậu lồng chậu","sân vườn","cây hoa theo mùa"]'::jsonb,
  $j$Cách trồng cây chậu lồng chậu: chôn chậu rỗng, thả chậu cây vào để đổi cây nhanh, rễ mát, cây không đổ. Các bước, lót sỏi chống úng mùa mưa.$j$,
